export function sortedByScore(rows) {
  return [...rows].sort((left, right) => right.score - left.score);
}

files.test/sort.test.js:
import test from "node:test";
import assert from "node:assert/strict";

import { sortedByScore } from "../src/sort.js";

test("the caller's array is not reordered", () => {
  const rows = [{ score: 1 }, { score: 3 }];
  const sorted = sortedByScore(rows);
  assert.deepEqual(sorted.map((row) => row.score), [3, 1]);
  assert.deepEqual(rows.map((row) => row.score), [1, 3]);
});

